static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GooglenetInceptionModuleCustomTilingData tiling;

    auto s0 = context->GetInputShape(0)->GetOriginalShape();
    auto s1 = context->GetInputShape(1)->GetOriginalShape();
    auto s2 = context->GetInputShape(2)->GetOriginalShape();
    auto s3 = context->GetInputShape(3)->GetOriginalShape();

    uint32_t n = static_cast<uint32_t>(s0.GetDim(0));
    uint32_t c1 = static_cast<uint32_t>(s0.GetDim(1));
    uint32_t h = static_cast<uint32_t>(s0.GetDim(2));
    uint32_t w = static_cast<uint32_t>(s0.GetDim(3));

    uint32_t c2 = static_cast<uint32_t>(s1.GetDim(1));
    uint32_t c3 = static_cast<uint32_t>(s2.GetDim(1));
    uint32_t c4 = static_cast<uint32_t>(s3.GetDim(1));

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_n(n);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_c1(c1);
    tiling.set_c2(c2);
    tiling.set_c3(c3);
    tiling.set_c4(c4);
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
